from pathlib import Path

path = Path('app/classifieds/page.tsx')
s = path.read_text()

# 1) Extend JobCard with owner ids.
old = '''  description: string;\n};'''
new = '''  description: string;\n  ownerOfficeId?: string | null;\n  ownerProfessionalId?: string | null;\n};'''
assert old in s
s = s.replace(old, new, 1)

# 2) Add connection type after PostingPreview.
marker = '''type PostingPreview = {\n  position: string;\n  employment: string;\n  city: string;\n  province: string;\n  days: string;\n  payFrom: string;\n  payTo: string;\n  schedule: string;\n  description: string;\n};\n'''
insert = marker + '''\ntype JobConnection = {\n  id: string;\n  listingId: string;\n  professionalId: string;\n  officeId: string;\n  initiatorRole: "professional" | "office";\n  status: "pending" | "interested" | "declined" | "withdrawn";\n  message: string;\n  resumePath: string | null;\n  createdAt: string;\n  profession: string;\n  employment: string;\n  city: string;\n  province: string;\n  listingType: "office_hiring" | "professional_available";\n};\n'''
assert marker in s
s = s.replace(marker, insert, 1)

# 3) Add state.
marker = '''  const [manageError, setManageError] = useState("");\n'''
insert = marker + '''  const [resumePath, setResumePath] = useState<string | null>(null);\n  const [connections, setConnections] = useState<JobConnection[]>([]);\n  const [selectedOpportunity, setSelectedOpportunity] = useState<JobCard | null>(null);\n  const [connectionMessage, setConnectionMessage] = useState("");\n  const [connectionBusy, setConnectionBusy] = useState(false);\n  const [connectionError, setConnectionError] = useState("");\n'''
assert marker in s
s = s.replace(marker, insert, 1)

# 4) Office account startup loads connections.
old = '''          if (details.office?.id) await loadMyOfficeJobs(details.office.id);'''
new = '''          if (details.office?.id) await loadMyOfficeJobs(details.office.id);\n          await loadConnections();'''
assert old in s
s = s.replace(old, new, 1)

# 5) Professional startup loads resume + connections.
old = '''          setProfessionalProfession(details.professional.profession || "");\n          await loadMyProfessionalJobs(user.id);'''
new = '''          setProfessionalProfession(details.professional.profession || "");\n          const { data: professionalRow } = await supabase.from("professional_profiles").select("resume_path").eq("user_id", user.id).maybeSingle();\n          setResumePath(professionalRow?.resume_path || null);\n          await loadMyProfessionalJobs(user.id);\n          await loadConnections();'''
assert old in s
s = s.replace(old, new, 1)

# 6) Include owner ids in public listing fetch.
old = '''.select("id,listing_type,profession,employment_type,city,province,days_per_week,pay_min,pay_max,schedule,description,created_at")'''
new = '''.select("id,listing_type,profession,office_id,professional_id,employment_type,city,province,days_per_week,pay_min,pay_max,schedule,description,created_at")'''
assert old in s
s = s.replace(old, new, 1)

old = '''          description: row.description,\n        };'''
new = '''          description: row.description,\n          ownerOfficeId: row.office_id || null,\n          ownerProfessionalId: row.professional_id || null,\n        };'''
assert old in s
s = s.replace(old, new, 1)

# 7) Add connection functions before loadMyOfficeJobs.
marker = '''  const loadMyOfficeJobs = async (targetOfficeId: string) => {'''
block = '''  const loadConnections = async () => {\n    const { data, error } = await supabase\n      .from("job_applications")\n      .select("id,listing_id,professional_id,office_id,initiator_role,status,message,resume_path_snapshot,created_at,job_listings(profession,employment_type,city,province,listing_type)")\n      .order("created_at", { ascending: false });\n    if (error || !data) return;\n    setConnections((data as any[]).map((row) => {\n      const listing = Array.isArray(row.job_listings) ? row.job_listings[0] : row.job_listings;\n      return {\n        id: row.id, listingId: row.listing_id, professionalId: row.professional_id, officeId: row.office_id,\n        initiatorRole: row.initiator_role, status: row.status, message: row.message || "", resumePath: row.resume_path_snapshot || null,\n        createdAt: row.created_at, profession: listing?.profession || "Dental position", employment: listing?.employment_type || "",\n        city: listing?.city || "", province: listing?.province || "", listingType: listing?.listing_type || "office_hiring",\n      } as JobConnection;\n    }));\n  };\n\n  const existingConnectionFor = (ad: JobCard) => connections.find((item) => item.listingId === String(ad.id));\n\n  const openConnection = (ad: JobCard) => {\n    setConnectionError("");\n    setConnectionMessage("");\n    setSelectedOpportunity(ad);\n  };\n\n  const sendConnection = async () => {\n    if (!selectedOpportunity || !portalRole) return;\n    setConnectionError("");\n    setConnectionBusy(true);\n    try {\n      if (portalRole === "professional" && selectedOpportunity.kind === "office") {\n        if (!professionalId || !selectedOpportunity.ownerOfficeId) throw new Error("This opportunity is not available for applications yet.");\n        const { error } = await supabase.from("job_applications").insert({\n          listing_id: selectedOpportunity.id, professional_id: professionalId, office_id: selectedOpportunity.ownerOfficeId,\n          initiator_role: "professional", status: "pending", message: connectionMessage.trim() || null, resume_path_snapshot: resumePath,\n        });\n        if (error) { if (error.code === "23505") throw new Error("You have already applied to this opportunity."); throw error; }\n      } else if (portalRole === "office" && selectedOpportunity.kind === "professional") {\n        if (!officeId || !selectedOpportunity.ownerProfessionalId) throw new Error("This professional opportunity is not available for interest yet.");\n        const { error } = await supabase.from("job_applications").insert({\n          listing_id: selectedOpportunity.id, professional_id: selectedOpportunity.ownerProfessionalId, office_id: officeId,\n          initiator_role: "office", status: "pending", message: connectionMessage.trim() || null, resume_path_snapshot: null,\n        });\n        if (error) { if (error.code === "23505") throw new Error("Your office has already expressed interest in this professional."); throw error; }\n      } else {\n        throw new Error("This action is not available from your current portal.");\n      }\n      await loadConnections();\n      setSelectedOpportunity(null);\n      setConnectionMessage("");\n    } catch (value) {\n      setConnectionError(value instanceof Error ? value.message : "Could not send your interest.");\n    } finally { setConnectionBusy(false); }\n  };\n\n  const updateConnection = async (connection: JobConnection, action: "interested" | "declined" | "withdrawn") => {\n    setConnectionError("");\n    setConnectionBusy(true);\n    try {\n      const values: Record<string, unknown> = { status: action, updated_at: new Date().toISOString() };\n      if (action !== "withdrawn") values.responded_at = new Date().toISOString();\n      const { error } = await supabase.from("job_applications").update(values).eq("id", connection.id);\n      if (error) throw error;\n      await loadConnections();\n    } catch (value) {\n      setConnectionError(value instanceof Error ? value.message : "Could not update this connection.");\n    } finally { setConnectionBusy(false); }\n  };\n\n'''
assert marker in s
s = s.replace(marker, block + marker, 1)

# 8) Ensure new cards created after publishing carry owner IDs.
old = '''description: preview.description }, ...current]);'''
new = '''description: preview.description, ownerProfessionalId: professionalId }, ...current]);'''
assert old in s
s = s.replace(old, new, 1)
old = '''        description: preview.description,\n      }, ...current]);'''
new = '''        description: preview.description,\n        ownerOfficeId: officeId,\n      }, ...current]);'''
assert old in s
s = s.replace(old, new, 1)

# 9) Insert connections panel before search/filter panel.
marker = '''        <div className="mt-6 grid gap-3 rounded-2xl border-2 border-[#4285F4] bg-[#4285F4] p-3 shadow-md md:grid-cols-[1.4fr_.8fr_.9fr] lg:grid-cols-[1.5fr_.7fr_.9fr_auto]">'''
panel = '''        {portalRole && <section className="mt-6 rounded-2xl border border-[#002757]/15 bg-white p-4 shadow-sm sm:p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-[0.12em] text-[#4285F4]">DentalJobs connections</p><h2 className="mt-1 text-xl font-black text-[#002757]">{portalRole === "office" ? "Applications & Interest" : "My Applications & Office Interest"}</h2><p className="mt-1 text-sm text-slate-500">{portalRole === "office" ? "Review professionals who applied and track professionals your office contacted." : "Track your applications and offices that expressed interest in you."}</p></div><span className="rounded-full bg-[#edf3fa] px-3 py-1.5 text-xs font-black text-[#002757]">{connections.length} connection{connections.length === 1 ? "" : "s"}</span></div>{connectionError && <p className="mt-3 rounded-xl bg-rose-50 p-3 text-sm font-bold text-rose-700">{connectionError}</p>}<div className="mt-4 grid gap-3">{connections.length === 0 ? <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5 text-sm font-semibold text-slate-500">No DentalJobs applications or expressions of interest yet.</div> : connections.map((item) => { const initiatedByMe = item.initiatorRole === portalRole; const statusLabel = item.status === "interested" ? "Interested" : item.status === "declined" ? "Not Interested" : item.status === "withdrawn" ? "Withdrawn" : "Pending"; return <article key={item.id} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex flex-wrap gap-2"><span className={`rounded-full px-2.5 py-1 text-[11px] font-black uppercase ${item.status === "interested" ? "bg-[#eaf8ee] text-[#017f27]" : item.status === "declined" ? "bg-rose-50 text-rose-700" : item.status === "withdrawn" ? "bg-slate-100 text-slate-500" : "bg-amber-50 text-amber-700"}`}>{statusLabel}</span><span className="rounded-full bg-[#edf3fa] px-2.5 py-1 text-[11px] font-black text-[#002757]">{initiatedByMe ? "Sent by you" : "Received"}</span></div><h3 className="mt-2 font-black text-[#002757]">{item.profession}{item.employment ? ` — ${item.employment}` : ""}</h3><p className="mt-1 text-sm text-slate-500">{item.city}{item.city && item.province ? ", " : ""}{item.province}</p>{item.message && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">“{item.message}”</p>}{portalRole === "office" && item.resumePath && <p className="mt-2 inline-flex items-center gap-1.5 text-xs font-black text-[#01A32E]"><FileText size={14}/> Résumé/CV attached privately</p>}</div>{item.status === "pending" && <div className="flex flex-wrap gap-2 sm:justify-end">{initiatedByMe ? <button type="button" disabled={connectionBusy} onClick={() => void updateConnection(item,"withdrawn")} className="rounded-xl border border-slate-300 bg-white px-3.5 py-2 text-xs font-black text-slate-600 hover:bg-slate-50 disabled:opacity-50">Withdraw</button> : <><button type="button" disabled={connectionBusy} onClick={() => void updateConnection(item,"declined")} className="rounded-xl border border-rose-200 bg-white px-3.5 py-2 text-xs font-black text-rose-600 hover:bg-rose-50 disabled:opacity-50">Not Interested</button><button type="button" disabled={connectionBusy} onClick={() => void updateConnection(item,"interested")} className="rounded-xl bg-[#01A32E] px-3.5 py-2 text-xs font-black text-white shadow-sm hover:bg-[#018a28] disabled:opacity-50">Interested</button></>}</div>}</div></article>})}</div></section>}\n\n'''
assert marker in s
s = s.replace(marker, panel + marker, 1)

# 10) Replace card CTA with role-aware Apply / I'm Interested.
old = '''<button type="button" className={`rounded-xl px-4 py-2.5 text-sm font-black text-white shadow-md transition hover:-translate-y-0.5 hover:brightness-95 hover:shadow-lg ${ad.kind === "office" ? "bg-[#002757]" : ""}`} style={ad.kind === "professional" ? { backgroundColor: getProfessionalCardTheme(ad.profession).accent } : undefined}>View Opportunity</button>'''
new = '''{(() => { const existing = existingConnectionFor(ad); const actionable = (portalRole === "professional" && ad.kind === "office") || (portalRole === "office" && ad.kind === "professional"); const label = existing ? (existing.status === "pending" ? "Pending" : existing.status === "interested" ? "Interested" : existing.status === "declined" ? "Not Interested" : "Withdrawn") : portalRole === "professional" && ad.kind === "office" ? "Apply" : portalRole === "office" && ad.kind === "professional" ? "I'm Interested" : "View Opportunity"; return <button type="button" disabled={Boolean(existing) || !actionable} onClick={() => actionable && !existing && openConnection(ad)} className={`rounded-xl px-4 py-2.5 text-sm font-black text-white shadow-md transition hover:-translate-y-0.5 hover:brightness-95 hover:shadow-lg disabled:cursor-default disabled:opacity-70 ${ad.kind === "office" ? "bg-[#002757]" : ""}`} style={ad.kind === "professional" ? { backgroundColor: getProfessionalCardTheme(ad.profession).accent } : undefined}>{label}</button>; })()}'''
assert old in s
s = s.replace(old, new, 1)

# 11) Insert connection modal before posting modal.
marker = '''    {postingMode && <div className="fixed inset-0 z-[90] overflow-y-auto bg-[#002757]/65 p-4 sm:p-6">'''
modal = '''    {selectedOpportunity && <div className="fixed inset-0 z-[95] overflow-y-auto bg-[#002757]/65 p-4 sm:p-6"><button type="button" aria-label="Close connection form" onClick={() => setSelectedOpportunity(null)} className="fixed inset-0" /><section role="dialog" aria-modal="true" className="relative mx-auto my-8 w-full max-w-xl overflow-hidden rounded-3xl bg-white shadow-2xl"><div className="border-b border-slate-200 p-5 sm:p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-black uppercase tracking-[0.12em] text-[#4285F4]">DentalJobs</p><h2 className="mt-1 text-2xl font-black text-[#002757]">{portalRole === "professional" ? "Apply to this position" : "Express Interest"}</h2><p className="mt-2 text-sm leading-6 text-slate-500">Your direct contact information remains private at this stage.</p></div><button type="button" onClick={() => setSelectedOpportunity(null)} className="rounded-xl p-2 text-slate-500 hover:bg-slate-100"><X size={22}/></button></div></div><div className="p-5 sm:p-6"><div className="rounded-2xl border border-slate-200 bg-slate-50 p-4"><p className="text-xs font-black uppercase tracking-wide text-slate-400">Opportunity</p><h3 className="mt-1 font-black text-[#002757]">{selectedOpportunity.title}</h3><p className="mt-1 text-sm text-slate-500">{selectedOpportunity.city}</p></div>{portalRole === "professional" && <div className={`mt-4 rounded-2xl border p-4 ${resumePath ? "border-[#01A32E]/25 bg-[#f3fbf5]" : "border-amber-200 bg-amber-50"}`}><div className="flex items-start gap-3"><FileText size={20} className={resumePath ? "text-[#01A32E]" : "text-amber-600"}/><div><p className="font-black text-[#002757]">{resumePath ? "Résumé/CV attached from your profile" : "No résumé/CV currently on file"}</p><p className="mt-1 text-sm leading-6 text-slate-600">{resumePath ? "DentalShift will reference the private résumé stored in your professional account for this application." : "You can still send your application, but adding a résumé to your professional account will make it stronger."}</p></div></div></div>}<label className="mt-4 block"><span className="text-sm font-black text-[#002757]">Optional message</span><textarea value={connectionMessage} onChange={(e) => setConnectionMessage(e.target.value)} rows={4} maxLength={600} placeholder={portalRole === "professional" ? "Add a short note to the dental office…" : "Add a short note to the professional…"} className="mt-2 w-full rounded-2xl border border-slate-200 p-3 text-sm outline-none focus:border-[#4285F4]" /></label>{connectionError && <p className="mt-4 rounded-xl bg-rose-50 p-3 text-sm font-bold text-rose-700">{connectionError}</p>}<div className="mt-5 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end"><button type="button" disabled={connectionBusy} onClick={() => setSelectedOpportunity(null)} className="rounded-xl border border-slate-300 bg-white px-5 py-3 text-sm font-black text-[#002757] disabled:opacity-50">Cancel</button><button type="button" disabled={connectionBusy} onClick={() => void sendConnection()} className="rounded-xl bg-[#01A32E] px-5 py-3 text-sm font-black text-white shadow-sm hover:bg-[#018a28] disabled:opacity-50">{connectionBusy ? "Sending…" : portalRole === "professional" ? "Send Application" : "Send Interest"}</button></div></div></section></div>}\n\n'''
assert marker in s
s = s.replace(marker, modal + marker, 1)

path.write_text(s)
print('patched app/classifieds/page.tsx')
